require __DIR__.'/app/bootstrap.php';refresh_user();$user=current_user();if(!$user)redirect('/');$id=(int)($_GET['id']??0);$stmt=db()->prepare('SELECT j.*,u.email FROM jobs j JOIN users u ON u.id=j.user_id WHERE j.id=?');$stmt->bind_param('i',$id);$stmt->execute();$job=$stmt->get_result()->fetch_assoc();if(!$job||($user['role']!=='Admin'&&(int)$job['user_id']!==(int)$user['id'])){http_response_code(404);exit('Not found');}$path=__DIR__.'/storage/uploads/'.$job['stored_name'];if(!is_file($path)){http_response_code(404);exit('File not found');}header('Content-Type: '.$job['mime_type']);header('Content-Length: '.filesize($path));$downloadName=basename(str_replace(["\\","\r","\n",'\"'],['','','',''],$job['original_name']));header('Content-Disposition: attachment; filename="'.$downloadName.'"; filename*=UTF-8\'\''.rawurlencode($job['original_name']));readfile($path);
